[9550] = {id=9550,name="A Map to Where?",level=1,requiredLevel=1,faction="alliance",expansion=1,zoneID=3525,mapID=106,description="The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. If the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.",ends={{npcID=181756,x=0.612,y=0.418,mapID=106}},questType="standard"},
