[10430] = {id=10430,name="Testing the Prototype",level=25,requiredLevel=25,faction="both",expansion=1,zoneID=3523,mapID=109,description="I've been working on a portable generator repair kit for use in some of the harsher climates that the Consortium operates in. Granted, it wasn't designed for Netherstorm , but we shouldn't have any problems with it. I had already scheduled a test with one of my best techs up at Eco-Dome Farfield beyond the Netherstone to the northeast. Take this prototype to Tashar . He'll know what to do with it. If it works, we can use it to reinforce the shield generators at the larger domes.",starts={{npcID=20811,x=0.434,y=0.35,mapID=109}},ends={{npcID=20913,x=0.446,y=0.144,mapID=109}},coords={x=0.434,y=0.35,source="quest_giver",mapID=109},questType="standard"},
