[11072] = {id=11072,name="Adversarial Blood",level=15,requiredLevel=15,faction="none",expansion=1,zoneID=3519,mapID=108,description="The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager. They will all need to be slain before Terokk returns to this world. You will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis. Bring me a token from each one. These are powerful beings you will be facing; you would do well to bring friends.",questType="group"},
[11080] = {id=11080,name="The Relic's Emanation",level=20,requiredLevel=20,faction="both",expansion=1,zoneID=3522,mapID=105,description="Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings. We are very eager to benefit from your observations! As you progress in your ability to attune to the relics, you will gain a higher level of knowledge. This recognition will come in the form of an emanation from the relic. Return to us when you have attained such an emanation.",starts={{npcID=23233,x=0.288,y=0.574,mapID=105}},ends={{npcID=23233,x=0.288,y=0.574,mapID=105}},coords={x=0.288,y=0.574,source="quest_giver",mapID=105},questType="standard"},
